<?php
if(!defined('WHMCS'))die('Direct access denied');require_once __DIR__.'/bootstrap.php';require_once __DIR__.'/migrations/V100.php';require_once __DIR__.'/migrations/V110.php';require_once __DIR__.'/migrations/V120.php';require_once __DIR__.'/migrations/V130.php';require_once __DIR__.'/migrations/V140.php';
use CloudHost247\Foundation\Database\MigrationRunner;use CloudHost247\Ovh\Migrations\OvhInitialMigration;use CloudHost247\Ovh\Migrations\OvhOperationalMigration;use CloudHost247\Ovh\Migrations\OvhParityMigration;use CloudHost247\Ovh\Migrations\OvhDiscoveryMigration;use CloudHost247\Ovh\Migrations\HostingProductMigration;use CloudHost247\Ovh\Services\AdminController;
function cloudhost247_ovh_config(){return array('name'=>'CloudHost247 OVH','description'=>'Independent authenticated OVH catalog, mapping, provisioning and synchronization.','version'=>'1.3.0','author'=>'CloudHost247','language'=>'english','fields'=>array());}
function cloudhost247_ovh_activate(){try{$a=(new MigrationRunner())->run('cloudhost247_ovh',array(new OvhInitialMigration(),new OvhOperationalMigration(),new OvhParityMigration(),new OvhDiscoveryMigration(),new HostingProductMigration()));return array('status'=>'success','description'=>'OVH integration installed: '.($a?implode(', ',$a):'already current'));}catch(\Throwable$e){return array('status'=>'error','description'=>$e->getMessage());}}
function cloudhost247_ovh_deactivate(){return array('status'=>'success','description'=>'Data retained. OVH and WHMCS services were not modified or removed.');}
function cloudhost247_ovh_output($vars)
{
 $v=(new AdminController())->handle();$e=function($x){return htmlspecialchars((string)$x,ENT_QUOTES,'UTF-8');};
 echo '<h2>CloudHost247 OVH</h2><p class="alert alert-info">Credentials remain in WHMCS encrypted server fields: Username = application key, Password = application secret, Access Hash = consumer key.</p>';
 if($v['notice'])echo '<div class="alert alert-success">'.$e($v['notice']).'</div>';if($v['error'])echo '<div class="alert alert-danger">'.$e($v['error']).'</div>';
 echo '<h3>Endpoint configuration</h3><form method="post" class="form-inline"><input type="hidden" name="token" value="'.$e($v['token']).'"><input type="hidden" name="operation" value="endpoint"><input required class="form-control" name="name" placeholder="Account label"><select name="region" class="form-control"><option>eu</option><option>ca</option><option>us</option></select><select name="server_id" class="form-control">';
 foreach($v['servers'] as $server)echo '<option value="'.$e($server->id).'">'.$e($server->name).' ('.$e($server->type).')</option>';
 echo '</select><label><input type="checkbox" name="enabled" value="1"> Enabled</label> <button class="btn btn-primary">Save</button></form><h3>Connections and synchronization</h3><table class="table"><tr><th>Name</th><th>Region</th><th>Server</th><th>Actions</th></tr>';
 foreach($v['endpoints'] as $endpoint){echo '<tr><td>'.$e($endpoint->name).'</td><td>'.$e($endpoint->region).'</td><td>'.$e($endpoint->server_id).'</td><td><form method="post" class="form-inline"><input type="hidden" name="token" value="'.$e($v['token']).'"><input type="hidden" name="endpoint_id" value="'.$e($endpoint->id).'"><button name="operation" value="test" class="btn btn-xs btn-default">Test API</button> <input name="subsidiary" value="US" size="3" class="form-control"><select name="family" class="form-control"><option>eco</option><option>vps</option></select><button name="operation" value="catalog" class="btn btn-xs btn-default">Sync Catalog</button> <button name="operation" value="services" class="btn btn-xs btn-default">Sync Services</button></form></td></tr>';}
 echo '</table><h3>Product mapping</h3><form method="post" class="form-inline"><input type="hidden" name="token" value="'.$e($v['token']).'"><input type="hidden" name="operation" value="mapping"><select name="whmcs_product_id" class="form-control">';
 foreach($v['products'] as $product)echo '<option value="'.$e($product->id).'">'.$e($product->name).'</option>';
 echo '</select><select name="endpoint_id" class="form-control">';foreach($v['endpoints'] as $endpoint)echo '<option value="'.$e($endpoint->id).'">'.$e($endpoint->name).'</option>';
 echo '</select><select name="family" class="form-control"><option>eco</option><option>vps</option><option>dedicated</option></select><input required name="plan_code" class="form-control" placeholder="OVH plan code"><input required name="subsidiary" value="US" size="3" class="form-control"><input name="configuration_json" value="{}" class="form-control"><label><input type="checkbox" name="active" value="1"> Active</label> <button class="btn btn-primary">Save mapping</button></form>';
 echo '<h3>Configurable-option discovery</h3><form method="post" class="form-inline"><input type="hidden" name="token" value="'.$e($v['token']).'"><select name="mapping_id" class="form-control">';foreach($v['mappings'] as $mapping)echo '<option value="'.$e($mapping->id).'">Mapping #'.$e($mapping->id).'</option>';echo '</select><button name="operation" value="option_suggest" class="btn btn-default">Preview Exact Matches</button></form><form method="post" class="form-inline"><input type="hidden" name="token" value="'.$e($v['token']).'"><input name="mapping_id" type="number" required class="form-control" placeholder="Mapping ID"><input name="ovh_option_id" type="number" required class="form-control" placeholder="Discovered option ID"><input name="whmcs_option_id" type="number" required class="form-control" placeholder="WHMCS option ID"><input name="whmcs_suboption_id" type="number" class="form-control" placeholder="WHMCS suboption ID"><label><input type="checkbox" name="confirm" value="1"> Confirm exact match</label><button name="operation" value="option_confirm" class="btn btn-warning">Save Option Mapping</button></form>';
 echo '<h3>Order and existing-service reconciliation</h3><form method="post" class="form-inline"><input type="hidden" name="token" value="'.$e($v['token']).'"><button name="operation" value="poll" class="btn btn-default">Poll Pending Orders</button></form><form method="post" class="form-inline"><input type="hidden" name="token" value="'.$e($v['token']).'"><select name="endpoint_id" class="form-control">';foreach($v['endpoints'] as $endpoint)echo '<option value="'.$e($endpoint->id).'">'.$e($endpoint->name).'</option>';echo '</select><input name="query" class="form-control" placeholder="Remote service search"><button name="operation" value="search" class="btn btn-default">Search (read only)</button></form>';
 if($v['search']){echo '<table class="table"><tr><th>Remote service</th><th>Family</th><th>Linked</th></tr>';foreach($v['search'] as $item)echo '<tr><td>'.$e($item['remote_service_name']).'</td><td>'.$e($item['family']).'</td><td>'.($item['already_linked']?'Yes':'No').'</td></tr>';echo '</table>';}
 echo '<form method="post" class="form-inline"><input type="hidden" name="token" value="'.$e($v['token']).'"><select name="endpoint_id" class="form-control">';foreach($v['endpoints'] as $endpoint)echo '<option value="'.$e($endpoint->id).'">'.$e($endpoint->name).'</option>';echo '</select><select name="family" class="form-control"><option>dedicated</option><option>vps</option></select><input required name="remote_service_name" class="form-control" placeholder="Exact remote service"><select name="whmcs_service_id" class="form-control">';foreach($v['hosting'] as $hosting)echo '<option value="'.$e($hosting->id).'">#'.$e($hosting->id).' '.$e($hosting->domain).'</option>';echo '</select><button name="operation" value="link_preview" class="btn btn-default">Preview Match</button> <label><input type="checkbox" name="confirm" value="1"> Explicitly confirm link</label><button name="operation" value="link_confirm" class="btn btn-warning">Link Existing Service</button></form>';if($v['preview'])echo '<pre>'.htmlspecialchars(json_encode($v['preview'],JSON_PRETTY_PRINT),ENT_QUOTES,'UTF-8').'</pre>';
 echo '<h3>Pricing preview and explicit application</h3><form method="post" class="form-inline"><input type="hidden" name="token" value="'.$e($v['token']).'"><select name="mapping_id" class="form-control">';foreach($v['mappings'] as $mapping)echo '<option value="'.$e($mapping->id).'">Mapping #'.$e($mapping->id).' / Product #'.$e($mapping->whmcs_product_id).'</option>';echo '</select><select name="currency_id" class="form-control">';foreach($v['currencies'] as $currency)echo '<option value="'.$e($currency->id).'">'.$e($currency->code).'</option>';echo '</select><input name="source_price" type="number" min="0.000001" step="0.000001" required class="form-control" placeholder="OVH source price"><input name="source_currency" maxlength="3" required class="form-control" placeholder="Source currency"><select name="billing_cycle" class="form-control"><option>monthly</option><option>quarterly</option><option>semiannually</option><option>annually</option><option>biennially</option><option>triennially</option></select><select name="rounding_mode" class="form-control"><option>nearest</option><option>up</option><option>down</option></select><input name="precision" type="number" min="0" max="8" value="2" class="form-control"><button name="operation" value="price_preview" class="btn btn-default">Preview Only</button></form>';
 foreach($v['price_previews'] as $price)if($price->status==='preview')echo '<form method="post" class="form-inline"><input type="hidden" name="token" value="'.$e($v['token']).'"><input type="hidden" name="preview_id" value="'.$e($price->id).'"><span>Preview #'.$e($price->id).': '.$e($price->source_price).' '.$e($price->source_currency).' → '.$e($price->final_price).'</span> <label><input type="checkbox" name="confirm" value="1"> Confirm current product-price change</label><button name="operation" value="price_apply" class="btn btn-danger">Apply</button></form>';
 echo '<h3>Recent provisioning operations</h3><table class="table"><tr><th>ID</th><th>Service</th><th>Operation</th><th>Status</th><th>Remote ID</th><th>Error</th></tr>';
 foreach($v['operations'] as $operation)echo '<tr><td>'.$e($operation->id).'</td><td>'.$e($operation->whmcs_service_id).'</td><td>'.$e($operation->operation).'</td><td>'.$e($operation->status).'</td><td>'.$e($operation->remote_id).'</td><td>'.$e($operation->error_message).'</td></tr>';
 echo '</table>';
}
